CREATE TABLE IF NOT EXISTS challenge (id SERIAL PRIMARY KEY, title VARCHAR(255) NOT NULL, description TEXT NULL, is_visible BOOLEAN DEFAULT TRUE NOT NULL, publish_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, max_attempts INT NOT NULL, categories TEXT[] NOT NULL, time_limit INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
ALTER TABLE challenge ADD CONSTRAINT challenge_title_unique UNIQUE (title);
CREATE TABLE IF NOT EXISTS registrationcode (id SERIAL PRIMARY KEY, code VARCHAR(255) NOT NULL, max_uses INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, expires_at TIMESTAMP NOT NULL);
ALTER TABLE registrationcode ADD CONSTRAINT registrationcode_code_unique UNIQUE (code);
CREATE TABLE IF NOT EXISTS "User" (id SERIAL PRIMARY KEY, code_id INT NULL, username VARCHAR(64) NOT NULL, email VARCHAR(255) NOT NULL, password_hash VARCHAR(255) NOT NULL, "language" VARCHAR(35) NULL, country VARCHAR(2) NULL, website VARCHAR(255) NULL, "role" INT NOT NULL, is_verified BOOLEAN DEFAULT FALSE NOT NULL, is_hidden BOOLEAN DEFAULT FALSE NOT NULL, is_banned BOOLEAN DEFAULT FALSE NOT NULL, totp_secret VARCHAR(255) NULL, totp_enabled BOOLEAN DEFAULT FALSE NOT NULL, sound_enabled BOOLEAN DEFAULT TRUE NOT NULL, visibility_settings TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "version" INT DEFAULT 0 NOT NULL, CONSTRAINT fk_user_code_id__id FOREIGN KEY (code_id) REFERENCES registrationcode(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE "User" ADD CONSTRAINT user_username_unique UNIQUE (username);
ALTER TABLE "User" ADD CONSTRAINT user_email_unique UNIQUE (email);
CREATE TABLE IF NOT EXISTS challenge_starts (id SERIAL PRIMARY KEY, user_id INT NOT NULL, challenge_id INT NOT NULL, started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_challenge_starts_user_id__id FOREIGN KEY (user_id) REFERENCES "User"(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_challenge_starts_challenge_id__id FOREIGN KEY (challenge_id) REFERENCES challenge(id) ON DELETE CASCADE ON UPDATE RESTRICT);
ALTER TABLE challenge_starts ADD CONSTRAINT uq_challenge_starts_user_challenge UNIQUE (user_id, challenge_id);
CREATE TABLE IF NOT EXISTS emailtemplate (id SERIAL PRIMARY KEY, subject VARCHAR(255) NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
ALTER TABLE emailtemplate ADD CONSTRAINT emailtemplate_subject_unique UNIQUE (subject);
CREATE TABLE IF NOT EXISTS file (id SERIAL PRIMARY KEY, owner_type VARCHAR(64) NOT NULL, owner_id INT NOT NULL, filename VARCHAR(255) NOT NULL, storage_key VARCHAR(64) NOT NULL, "size" BIGINT NOT NULL, mime_type VARCHAR(128) NULL, sha256 VARCHAR(64) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
ALTER TABLE file ADD CONSTRAINT file_storage_key_unique UNIQUE (storage_key);
CREATE INDEX idx_files_owner ON file (owner_type, owner_id);
CREATE TABLE IF NOT EXISTS flag (id SERIAL PRIMARY KEY, challenge_id INT NOT NULL, pattern VARCHAR(255) NOT NULL, is_case_sensitive BOOLEAN NOT NULL, base_value INT NOT NULL, decay_value INT NULL, min_value INT NULL, decay_fun VARCHAR(50) DEFAULT 'static' NOT NULL, sort_order INT DEFAULT 1 NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_flag_challenge_id__id FOREIGN KEY (challenge_id) REFERENCES challenge(id) ON DELETE CASCADE ON UPDATE RESTRICT);
ALTER TABLE flag ADD CONSTRAINT flag_pattern_unique UNIQUE (pattern);
CREATE TABLE IF NOT EXISTS hint (id SERIAL PRIMARY KEY, challenge_id INT NOT NULL, body TEXT NOT NULL, "cost" INT DEFAULT 0 NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_hint_challenge_id__id FOREIGN KEY (challenge_id) REFERENCES challenge(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS team (id SERIAL PRIMARY KEY, "name" VARCHAR(64) NOT NULL, owner_id INT NOT NULL, country VARCHAR(2) NULL, website VARCHAR(255) NULL, is_hidden BOOLEAN DEFAULT FALSE NOT NULL, is_banned BOOLEAN DEFAULT FALSE NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_team_owner_id__id FOREIGN KEY (owner_id) REFERENCES "User"(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE team ADD CONSTRAINT team_name_unique UNIQUE ("name");
CREATE TABLE IF NOT EXISTS hintunlock (id SERIAL PRIMARY KEY, hint_id INT NOT NULL, user_id INT NOT NULL, team_id INT NULL, unlocked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_hintunlock_hint_id__id FOREIGN KEY (hint_id) REFERENCES hint(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_hintunlock_user_id__id FOREIGN KEY (user_id) REFERENCES "User"(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_hintunlock_team_id__id FOREIGN KEY (team_id) REFERENCES team(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE hintunlock ADD CONSTRAINT hintunlock_hint_id_user_id_unique UNIQUE (hint_id, user_id);
ALTER TABLE hintunlock ADD CONSTRAINT hintunlock_hint_id_team_id_unique UNIQUE (hint_id, team_id);
CREATE TABLE IF NOT EXISTS magiclink (id SERIAL PRIMARY KEY, user_id INT NOT NULL, token VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, expires_at TIMESTAMP NOT NULL, used_at TIMESTAMP NULL, CONSTRAINT fk_magiclink_user_id__id FOREIGN KEY (user_id) REFERENCES "User"(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE magiclink ADD CONSTRAINT magiclink_token_unique UNIQUE (token);
CREATE TABLE IF NOT EXISTS notification (id SERIAL PRIMARY KEY, title VARCHAR(255) NOT NULL, message TEXT NOT NULL, "type" INT NOT NULL, send_email BOOLEAN DEFAULT FALSE NOT NULL, push_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS page (id SERIAL PRIMARY KEY, title VARCHAR(255) NOT NULL, route VARCHAR(255) NOT NULL, "language" VARCHAR(35) DEFAULT 'en' NOT NULL, "format" VARCHAR(255) NOT NULL, target_blank BOOLEAN DEFAULT FALSE NOT NULL, body TEXT NOT NULL, is_hidden BOOLEAN DEFAULT FALSE NOT NULL, is_protected BOOLEAN DEFAULT FALSE NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
ALTER TABLE page ADD CONSTRAINT page_route_language_unique UNIQUE (route, "language");
CREATE TABLE IF NOT EXISTS passwordresettoken (id SERIAL PRIMARY KEY, user_id INT NOT NULL, token VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, expires_at TIMESTAMP NOT NULL, used_at TIMESTAMP NULL, CONSTRAINT fk_passwordresettoken_user_id__id FOREIGN KEY (user_id) REFERENCES "User"(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE passwordresettoken ADD CONSTRAINT passwordresettoken_token_unique UNIQUE (token);
CREATE TABLE IF NOT EXISTS submission (id SERIAL PRIMARY KEY, user_id INT NOT NULL, team_id INT NULL, challenge_id INT NOT NULL, flag_id INT NULL, submitted_flag TEXT NOT NULL, is_correct BOOLEAN NOT NULL, submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, ip_address VARCHAR(45) NULL, user_agent VARCHAR(512) NULL, CONSTRAINT fk_submission_user_id__id FOREIGN KEY (user_id) REFERENCES "User"(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_submission_team_id__id FOREIGN KEY (team_id) REFERENCES team(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_submission_challenge_id__id FOREIGN KEY (challenge_id) REFERENCES challenge(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_submission_flag_id__id FOREIGN KEY (flag_id) REFERENCES flag(id) ON DELETE SET NULL ON UPDATE RESTRICT);
CREATE INDEX idx_submissions_user_challenge ON submission (user_id, challenge_id);
CREATE UNIQUE INDEX uq_submissions_user_challenge_solved ON submission (user_id, challenge_id) WHERE submission.is_correct = TRUE;
CREATE TABLE IF NOT EXISTS teammember (id SERIAL PRIMARY KEY, team_id INT NOT NULL, user_id INT NOT NULL, joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_teammember_team_id__id FOREIGN KEY (team_id) REFERENCES team(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_teammember_user_id__id FOREIGN KEY (user_id) REFERENCES "User"(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE teammember ADD CONSTRAINT teammember_team_id_user_id_unique UNIQUE (team_id, user_id);
